{
  "name": "HP 3325A 合成函数发生器",
  "name_en": "HP 3325A Synthesizer/Function Generator",
  "manufacturer": "Hewlett-Packard",
  "description": "HP 3325A 是一台 20 MHz 台式合成函数发生器，可输出正弦波、方波、三角波和斜坡波，并支持幅度调制、相位调制以及直流偏置。它常用于电子、电路与仪器实验中的激励信号产生、频率响应测试、校准和通用台架测量。",
  "description_en": "The HP 3325A is a 20 MHz bench-top synthesizer/function generator that can produce sine, square, triangle, and ramp waveforms, with support for amplitude modulation, phase modulation, and DC offset. It is commonly used in electronics and instrumentation labs for stimulus generation, frequency-response testing, calibration, and general bench measurements.",
  "tag_hints": [
    "function generator",
    "frequency synthesizer",
    "signal source",
    "waveform generation",
    "amplitude modulation",
    "phase control",
    "20 MHz test instrument"
  ],
  "actions": [
    {
      "action_name": "auto-amplitude",
      "description": "获取/设置/定义输出幅度",
      "description_en": "get/set/define the output amplitude"
    },
    {
      "action_name": "auto-amplitude_calibration",
      "description": "执行幅度校准",
      "description_en": "perform amplitude calibration"
    },
    {
      "action_name": "auto-amplitude_modulation",
      "description": "获取/设置/定义幅度调制设置",
      "description_en": "get/set/define the amplitude modulation setting"
    },
    {
      "action_name": "auto-assign_zero_phase",
      "description": "将当前相位设为零相位参考",
      "description_en": "assign the current phase as the zero-phase reference"
    },
    {
      "action_name": "auto-frequency",
      "description": "获取/设置/定义输出频率",
      "description_en": "get/set/define the output frequency"
    },
    {
      "action_name": "auto-function",
      "description": "获取/设置/定义输出波形类型",
      "description_en": "get/set/define the output waveform type"
    },
    {
      "action_name": "auto-high_voltage",
      "description": "获取/设置/定义高电压输出设置",
      "description_en": "get/set/define the high-voltage output setting"
    },
    {
      "action_name": "auto-marker_frequency",
      "description": "获取/设置/定义标记频率",
      "description_en": "get/set/define the marker frequency"
    },
    {
      "action_name": "auto-offset",
      "description": "获取/设置/定义直流偏置",
      "description_en": "get/set/define the DC offset"
    },
    {
      "action_name": "auto-phase",
      "description": "获取/设置/定义输出相位",
      "description_en": "get/set/define the output phase"
    },
    {
      "action_name": "auto-query",
      "description": "发送底层设备查询命令并读取响应",
      "description_en": "send a low-level device query command and read the response"
    },
    {
      "action_name": "auto-query_error",
      "description": "查询设备错误状态",
      "description_en": "query the device error status"
    }
  ]
}

